local C = {}
C.name = 'Mon nœud'
C.description = 'Fait quelque chose.'
C.category = 'once_p_duration'
C.pinSchema = {
  {dir = 'in', type = 'number', name = 'valeur', default = 1, description = 'Entrée.'},
  {dir = 'out', type = 'number', name = 'resultat', description = 'Sortie.'},
}
